            let body = recorded_body(group.prefix, scenario, interaction);
            let frames = decode_frames(&body);
            assert_eq!(
                serde_json::to_value(&frames).unwrap(),
                dump["frames"],
                "frames diverge: {}",
                dump_path.display()
            );

            let request = request_for(group);
